<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { NavigationMenuItemState, getNavigationMenuContext, setNavigationMenuItemContext } from './navigation-menu-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLLIElement>, 'children'> { children?: Snippet; value: string; ref?: HTMLLIElement | null; } let { children, value, ref = $bindable(null), ...rest }: Props = $props(); const uid = $props.id(); const navigation = getNavigationMenuContext(); const item = setNavigationMenuItemContext(new NavigationMenuItemState()); item.triggerId = `${uid}-trigger`; item.contentId = `${uid}-content`; $effect.pre(() => { item.value = value; }); let open = $derived(navigation.value === value);</script><li bind:this={ref} {...rest} data-open={open ? '' : undefined}>{@render children?.()}</li>
